static struct sg_table * vb2_dma_sg_dmabuf_ops_map ( struct dma_buf_attachment * db_attach , enum dma_data_direction dma_dir ) { struct vb2_dma_sg_attachment * attach = db_attach -> priv ; struct sg_table * sgt ; sgt = & attach -> sgt ; if ( attach -> dma_dir != DMA_NONE ) { dma_unmap_sgtable ( db_attach -> dev , sgt , attach -> dma_dir , 0 ) ; attach -> dma_dir = DMA_NONE ; } if ( dma_map_sgtable ( db_attach -> dev , sgt , dma_dir , 0 ) ) { pr_err ( "failed to map scatterlist\n" ) ; return ERR_PTR ( - EIO ) ; } attach -> dma_dir = dma_dir ; return sgt ; } 